#include <cstdio>
#include <algorithm>
#include <vector>
#include <stack>

using namespace std;

int get_value()
{
    int val;
    scanf("%d",&val);
    return val;
}

bool visited_nodes[1000007];
const int MOD=1000000007;
long long divisor_counts[1000007];
long long cycle_sizes[1000007];
long long dp_array[1000007];

int main()
{
    long long total=1;
    int p_val, k_val;
    p_val=get_value();
    k_val=get_value();
    for(int i=0; i<p_val; i++)
    {
        if(!visited_nodes[i])
        {
            int length=0;
            long long current=i;
            while(!visited_nodes[current])
            {
                visited_nodes[current]=1;
                current=((long long)k_val*current)%p_val;
                length++;
            }
            cycle_sizes[length]++;
        }
    }
    for(int i=1; i<=p_val; i++)
    {
        dp_array[i]=((long long)cycle_sizes[i]*i)%MOD;
    }
    for(int i=1; i<=p_val; i++)
    {
        divisor_counts[i]=(divisor_counts[i]+dp_array[i])%MOD;
        for(int j=i+i; j<=p_val; j+=i)
        {
            divisor_counts[j]=(dp_array[i]+divisor_counts[j])%MOD;
        }
    }
    for(int i=1; i<=p_val; i++)
    {
        if(i==1)
        {
            for(int j=0; j<cycle_sizes[i]-1; j++)
                total=(total*(long long)cycle_sizes[i])%MOD;
        }
        else
        {
            for(int j=0; j<cycle_sizes[i]; j++)
                total=(total*(long long)divisor_counts[i])%MOD;
        }
    }
    if(k_val==1) total=(total*divisor_counts[1])%MOD;
    printf("%lld", total);
    return 0;
}
